head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getFocusedRowStatus]<br/>포커스된 Cell 의 Row 상태값을 반환합니다.",
    "validation" : [
        "rowStatusVisible 속성이 false 로 RowStatus Column 이 표시되지 않는 상태에서도 Row 상태값을 반환하여야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (rowStatusVisible=false 로 Row 상태 컬럼 숨김)
    $c.gcm.createBasicGridView('dataList="data:dlt_bind" useShiftKey="true" rowStatusVisible="false"');

    // Row 상태값 변경 (R, U, C, D, V 상태 생성)
    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
}



// Row 삽입 (C 상태 생성, 삽입 후 삭제하여 V 상태 생성)
scwin.btn_insertRow_onclick = function () {
    let insertIndex = dlt_bind.insertRow();
    dlt_bind.setRowData(insertIndex, ["insert1", "insert2", "insert3", "insert4"], true);

    insertIndex = dlt_bind.insertRow();
    dlt_bind.setRowData(insertIndex, ["insert5", "insert6", "insert7", "insert8"], true);

    // 삽입 후 삭제하여 V 상태 생성
    dlt_bind.deleteRow(insertIndex);
};



// Row 삭제 (D 상태 생성)
scwin.btn_deleteRow_onclick = function () {
    dlt_bind.deleteRow(0);
};



// Cell 데이터 변경 (U 상태 생성)
scwin.btn_setCellData_onclick = function () {
    dlt_bind.setCellData(2, "col1", "change");
}



scwin.btn_getFocusedRowStatus_onclick = function () {
    let rtn = target1.getFocusedRowStatus();
    wf_body_bottom.getObj("scwin").setReturnValue("getFocusedRowStatus : " + rtn);
}
